    inc = [arr[i] for i in range(n)]
    dec = [arr[i] for i in range(n)]

    # Compute the maximum sum increasing subsequence for each element
    for i in range(1, n):
        for j in range(0, i):
            if arr[i] > arr[j] and inc[i] < inc[j] + arr[i]:
                inc[i] = inc[j] + arr[i]

    # Compute the maximum sum decreasing subsequence for each element
    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if arr[i] > arr[j] and dec[i] < dec[j] + arr[i]:
                dec[i] = dec[j] + arr[i]

    # Find the maximum sum of bitonic subsequence
    max_sum_bitonic = 0
    for i in range(n):
