def set_left_most_unset_bit(n): 
    if (n & (n + 1) == 0): 
        return n 
    i = 0
    temp = n 
    while (temp > 0): 
        if (temp & 1) == 0: 
            n = n | (1 << i) 
        i += 1
        temp >>= 1
    return n
